def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def round_div(n, d):
    """Quotient n/d rounded half away from zero (d > 0)."""
    if not _is_int(n) or not _is_int(d):
        raise MoneyError("round_div needs integers, got %r and %r" % (raw(n), raw(d)))
    if d <= 0:
        raise MoneyError("round_div needs a positive divisor, got %r" % (raw(d),))
    q, r = divmod(abs(n), d)
    if 2 * r >= d:
        q += 1
    return q if n >= 0 else -q


